<?php require_once 'config/auth.php'; require_admin(); $pageTitle='Productos';
$edit=null; if(isset($_GET['editar'])){$st=$pdo->prepare('SELECT * FROM producto WHERE id_producto=?');$st->execute([(int)$_GET['editar']]);$edit=$st->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??'';
 if($action==='save'){
  $id=(int)($_POST['id_producto']??0);$cat=(int)$_POST['id_categoria'];$codigo=trim($_POST['codigo']);$nombre=trim($_POST['nombre']);$unidad=trim($_POST['unidad']);$precio=(float)($_POST['precio_referencia']??0);$min=(int)($_POST['stock_minimo']??0);
  if(!$codigo||!$nombre||!$unidad||$cat<=0||$precio<0||$min<0){flash('danger','Completa los campos obligatorios correctamente.');redirect('productos.php');}
  try{if($id){$pdo->prepare('UPDATE producto SET id_categoria=?,codigo=?,nombre=?,unidad=?,precio_referencia=?,stock_minimo=? WHERE id_producto=?')->execute([$cat,$codigo,$nombre,$unidad,$precio,$min,$id]);flash('success','Producto actualizado.');}else{$pdo->prepare('INSERT INTO producto(id_categoria,codigo,nombre,unidad,precio_referencia,stock_actual,stock_minimo) VALUES(?,?,?,?,?,0,?)')->execute([$cat,$codigo,$nombre,$unidad,$precio,$min]);flash('success','Producto creado.');}}catch(PDOException $e){flash('danger','No se pudo guardar. Verifica que el código no esté repetido.');} redirect('productos.php');
 }
 if($action==='toggle'){$id=(int)$_POST['id'];$pdo->prepare('UPDATE producto SET estado=1-estado WHERE id_producto=?')->execute([$id]);flash('success','Estado del producto actualizado.');redirect('productos.php');}
}
$cats=$pdo->query('SELECT * FROM categoria WHERE estado=1 ORDER BY nombre')->fetchAll();$rows=$pdo->query('SELECT p.*,c.nombre categoria FROM producto p JOIN categoria c ON c.id_categoria=p.id_categoria ORDER BY p.estado DESC,p.nombre')->fetchAll(); require 'partials/header.php'; ?>
<div class="page-head"><div><span class="eyebrow">ADMINISTRACIÓN</span><h1>Productos</h1><p>Crear, actualizar y activar/desactivar productos.</p></div></div>
<div class="two-col admin-grid"><section class="panel"><div class="panel-head"><h2><?=$edit?'Editar producto':'Nuevo producto'?></h2><?php if($edit):?><a href="productos.php">Cancelar</a><?php endif;?></div><form method="post" class="form"><input type="hidden" name="action" value="save"><input type="hidden" name="id_producto" value="<?=$edit['id_producto']??0?>"><label>Código<input name="codigo" maxlength="50" required value="<?=e($edit['codigo']??'')?>"></label><label>Nombre<input name="nombre" maxlength="120" required value="<?=e($edit['nombre']??'')?>"></label><label>Categoría<select name="id_categoria" required><?php foreach($cats as $c):?><option value="<?=$c['id_categoria']?>" <?=isset($edit['id_categoria'])&&(int)$edit['id_categoria']===(int)$c['id_categoria']?'selected':''?>><?=e($c['nombre'])?></option><?php endforeach;?></select></label><label>Unidad<input name="unidad" maxlength="30" required value="<?=e($edit['unidad']??'unidad')?>"></label><label>Precio de referencia<input type="number" name="precio_referencia" min="0" step="0.01" required value="<?=e((string)($edit['precio_referencia']??0))?>"></label><label>Stock mínimo<input type="number" name="stock_minimo" min="0" required value="<?=e((string)($edit['stock_minimo']??0))?>"></label><button class="btn primary">Guardar producto</button></form></section>
<section class="panel"><div class="panel-head"><h2>Listado</h2><span class="muted"><?=count($rows)?> registros</span></div><div class="table-wrap"><table><thead><tr><th>Producto</th><th>Stock</th><th>Mínimo</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['nombre'])?></b><small><?=e($r['codigo'])?> · <?=e($r['categoria'])?></small></td><td><?=e((string)$r['stock_actual'])?></td><td><?=e((string)$r['stock_minimo'])?></td><td><?=$r['estado']?'<span class="badge success">Activo</span>':'<span class="badge">Inactivo</span>'?></td><td class="actions"><a href="productos.php?editar=<?=$r['id_producto']?>">Editar</a><form method="post" class="inline-form"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id_producto']?>"><button class="link-btn" data-confirm="¿Cambiar el estado de este producto?"><?=$r['estado']?'Desactivar':'Activar'?></button></form></td></tr><?php endforeach;?></tbody></table></div></section></div>
<?php require 'partials/footer.php'; ?>
